// OpenWA core webhook delivery: { event: 'message.received', sessionId, data: {...} }.
// Voice notes carry the audio inline as data.media.data (base64) unless it exceeded
// WEBHOOK_MEDIA_INLINE_MAX_BYTES, in which case media.omitted is set and we download it.
const VOICE_TYPES = ['voice', 'ptt', 'audio'];
const allowed = ($env.ALLOWED_PHONE_NUMBERS || '').split(',').map(s => s.replace(/\D/g, '')).filter(Boolean);

const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const data = body.data || {};
  if (body.event !== 'message.received' || data.fromMe || data.isGroupMsg) continue;

  const chatId = data.chatId || data.from || '';
  const phone = (data.senderPhone || data.from || '').split('@')[0].replace(/\D/g, '');
  if (!chatId.endsWith('@c.us') && !chatId.endsWith('@lid')) continue; // skip groups, status, newsletters
  if (allowed.length && !allowed.includes(phone)) continue;

  const isVoice = VOICE_TYPES.includes(data.type);
  const text = isVoice ? '' : (data.body || '').trim();
  if (!isVoice && (data.type !== 'chat' || !text)) continue;

  const result = { json: { chatId, phone, messageId: data.id || null, isVoice, text } };
  if (isVoice) {
    const media = data.media || {};
    let b64 = media.data;
    if (!b64) {
      const buf = await this.helpers.httpRequest({
        method: 'GET',
        url: `${$env.OPENWA_URL}/api/sessions/${$env.OPENWA_SESSION_ID}/messages/${encodeURIComponent(chatId)}/${encodeURIComponent(data.id)}/media`,
        headers: { 'X-API-Key': $env.OPENWA_API_KEY },
        encoding: 'arraybuffer',
      });
      b64 = Buffer.from(buf).toString('base64');
    }
    result.binary = { audio: { data: b64, mimeType: (media.mimetype || 'audio/ogg').split(';')[0], fileName: 'voice.ogg' } };
  }
  out.push(result);
}
return out;

// One Claude turn with tool use. The system prompt and tool schemas are the same files the
// real-time bot uses (mounted at /shared), and tools are executed by this n8n's own
// /webhook/tool workflow, so both channels behave the same.
const fs = require('fs');
const inbound = $('Prepare Inbound').first().json;
const text = (inbound.isVoice ? $json.text : inbound.text || '').trim();
if (!text) return [];

const system = fs.readFileSync('/shared/system.md', 'utf8') +
  `\nThis conversation is over WhatsApp voice notes. The customer's WhatsApp number is ${inbound.phone || 'unknown'}.`;
const tools = JSON.parse(fs.readFileSync('/shared/tools.json', 'utf8'));

// Short per-chat history in workflow static data (persists for active, production executions).
const store = $getWorkflowStaticData('global');
store.history = store.history || {};
const history = (store.history[inbound.chatId] || []).slice(-12);
const messages = [...history, { role: 'user', content: text }];

const callClaude = (msgs) => this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
  body: { model: $env.CLAUDE_MODEL || 'claude-haiku-4-5', max_tokens: 400, system, tools, messages: msgs },
  json: true,
});

let reply = '';
for (let turn = 0; turn < 4; turn++) {
  const res = await callClaude(messages);
  messages.push({ role: 'assistant', content: res.content });
  const toolUses = res.content.filter(b => b.type === 'tool_use');
  if (res.stop_reason !== 'tool_use' || !toolUses.length) {
    reply = res.content.filter(b => b.type === 'text').map(b => b.text).join(' ').trim();
    break;
  }
  const results = [];
  for (const t of toolUses) {
    let output;
    try {
      output = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://localhost:5678/webhook/tool',
        headers: { 'X-Tools-Secret': $env.TOOLS_SECRET },
        body: { tool: t.name, input: t.input, channel: 'whatsapp', phone: inbound.phone },
        json: true,
      });
    } catch (e) {
      output = { error: `Tool ${t.name} failed: ${e.message}` };
    }
    results.push({ type: 'tool_result', tool_use_id: t.id, content: JSON.stringify(output) });
  }
  messages.push({ role: 'user', content: results });
}
if (!reply) reply = "Sorry, I couldn't sort that out just now. Someone will get back to you shortly.";

// Keep only plain text turns in history; tool round-trips aren't needed for later context.
store.history[inbound.chatId] = [...history, { role: 'user', content: text }, { role: 'assistant', content: reply }].slice(-12);
return [{ json: { chatId: inbound.chatId, messageId: inbound.messageId, transcript: text, reply } }];

const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({ json: { chatId: $('Agent Reply').first().json.chatId, base64: buf.toString('base64') } });
}
return out;
